package sbs.osrstracker;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

@ConfigGroup("osrstracker")
public interface OsrsTrackerConfig extends Config
{
	@ConfigSection(
		name = "Reverse Sailing Alert",
		description = "Warn when your boat is moving backward relative to the way it's facing",
		position = 0
	)
	String sailingSection = "sailing";

	@ConfigItem(
		keyName = "reverseSailingAlert",
		name = "Enable alert",
		description = "Shows an on-screen warning and a notification when your boat is sailing in reverse",
		section = sailingSection
	)
	default boolean reverseSailingAlert()
	{
		return true;
	}

	@ConfigItem(
		keyName = "reverseThresholdDegrees",
		name = "Reverse angle threshold",
		description = "Heading-vs-movement angle, in degrees (0-180), beyond which the boat is considered to be moving in reverse",
		section = sailingSection
	)
	default int reverseThresholdDegrees()
	{
		return 135;
	}

	@ConfigItem(
		keyName = "headingCalibration",
		name = "Heading calibration (degrees)",
		description = "While sailing forward the overlay should read close to 0. If it instead reads close to 180, set this to 180. See README for details.",
		section = sailingSection
	)
	default int headingCalibration()
	{
		return 0;
	}

	@ConfigSection(
		name = "Price Checker",
		description = "Right-click link to view item prices on osrstracker.app",
		position = 1
	)
	String priceCheckerSection = "priceChecker";

	@ConfigItem(
		keyName = "showItemLink",
		name = "Show \"View on OSRS Tracker\" link",
		description = "Adds a right-click option on inventory, bank, equipped, Grand Exchange and shop items that opens the item's live price page on osrstracker.app",
		section = priceCheckerSection
	)
	default boolean showItemLink()
	{
		return true;
	}
}

package sbs.osrstracker;

import com.google.inject.Provides;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.MenuAction;
import net.runelite.api.Player;
import net.runelite.api.WorldEntity;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.Notifier;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.LinkBrowser;

/**
 * Helm Assist:
 *  - Warns when your boat is sailing in reverse relative to its heading.
 *  - Adds a "View on OSRS Tracker" right-click price-check link to items in
 *    the inventory, bank, equipment, Grand Exchange (search/offer screen)
 *    and NPC shop interfaces.
 */
@PluginDescriptor(
	name = "Helm Assist",
	description = "Warns when your boat is sailing in reverse. Also adds a quick price-check link to inventory, bank, equipment, Grand Exchange and shop items.",
	tags = {"sailing", "boat", "helm", "reverse", "ge", "grand exchange", "price", "tracker", "shop"}
)
public class OsrsTrackerPlugin extends Plugin
{
	private static final String MENU_OPTION = "View on OSRS Tracker";
	private static final String BASE_ITEM_URL = "https://osrstracker.app/item/";

	// OSRS/RuneLite angle unit: a full circle is 2048 "jau".
	private static final double JAU_PER_DEGREE = 2048.0 / 360.0;

	@Inject
	private Client client;

	@Inject
	private ItemManager itemManager;

	@Inject
	private Notifier notifier;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ReverseSailingOverlay reverseSailingOverlay;

	@Inject
	private OsrsTrackerConfig config;

	private boolean wasReversing;

	@Provides
	OsrsTrackerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(OsrsTrackerConfig.class);
	}

	@Override
	protected void startUp()
	{
		overlayManager.add(reverseSailingOverlay);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(reverseSailingOverlay);
		wasReversing = false;
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (!config.reverseSailingAlert())
		{
			reverseSailingOverlay.update(null, false);
			return;
		}

		Player player = client.getLocalPlayer();
		if (player == null || player.getWorldView().isTopLevel())
		{
			// Not aboard a boat.
			wasReversing = false;
			reverseSailingOverlay.update(null, false);
			return;
		}

		WorldEntity boat = findBoat(player.getWorldView().getId());
		if (boat == null)
		{
			reverseSailingOverlay.update(null, false);
			return;
		}

		LocalPoint loc = boat.getLocalLocation();
		LocalPoint target = boat.getTargetLocation();
		int dx = target.getX() - loc.getX();
		int dy = target.getY() - loc.getY();

		if (dx == 0 && dy == 0)
		{
			// Boat isn't moving this tick.
			wasReversing = false;
			reverseSailingOverlay.update(null, false);
			return;
		}

		// Angle of actual movement vs. the direction the boat is facing.
		// A consistent angle convention is used for both sides of the
		// comparison, so a 0-180 result correctly distinguishes "moving
		// the way it's facing" from "moving the opposite way" regardless
		// of which compass direction jau=0 represents. The calibration
		// offset covers the case where the two conventions are 180 (or
		// 90/270) degrees apart - see headingCalibration in the config.
		double movementJau = Math.atan2(dx, dy) / (2 * Math.PI) * 2048.0;
		double boatJau = boat.getOrientation() + config.headingCalibration() * JAU_PER_DEGREE;

		double diff = Math.abs(movementJau - boatJau) % 2048.0;
		if (diff > 1024.0)
		{
			diff = 2048.0 - diff;
		}
		double diffDegrees = diff / JAU_PER_DEGREE;

		boolean reversing = diffDegrees > config.reverseThresholdDegrees();
		reverseSailingOverlay.update(diffDegrees, reversing);

		if (reversing && !wasReversing)
		{
			notifier.notify("Sailing in reverse!");
		}
		wasReversing = reversing;
	}

	private WorldEntity findBoat(int worldViewId)
	{
		for (WorldEntity entity : client.getTopLevelWorldView().worldEntities())
		{
			if (entity.getWorldView().getId() == worldViewId)
			{
				return entity;
			}
		}
		return null;
	}

	@Subscribe
	public void onMenuEntryAdded(MenuEntryAdded event)
	{
		if (!config.showItemLink())
		{
			return;
		}

		// Widget-sourced menu entries encode the widget id (group << 16 | child) in
		// param1 and the slot/index within that widget in param0.
		final int widgetId = event.getActionParam1();
		final int groupId = widgetId >>> 16;
		final int slot = event.getActionParam0();

		final int itemId;

		if (groupId == InterfaceID.INVENTORY || groupId == InterfaceID.BANKMAIN || groupId == InterfaceID.EQUIPMENT)
		{
			// These widgets are backed by an ItemContainer, and the slot index
			// matches the container slot 1:1.
			final InventoryID inventoryId;
			if (groupId == InterfaceID.INVENTORY)
			{
				inventoryId = InventoryID.INVENTORY;
			}
			else if (groupId == InterfaceID.BANKMAIN)
			{
				inventoryId = InventoryID.BANK;
			}
			else
			{
				inventoryId = InventoryID.EQUIPMENT;
			}

			final ItemContainer container = client.getItemContainer(inventoryId);
			if (container == null)
			{
				return;
			}

			final Item item = container.getItem(slot);
			if (item == null || item.getId() <= 0)
			{
				return;
			}

			itemId = itemManager.canonicalize(item.getId());
		}
		else if (widgetId == InterfaceID.GePricechecker.ITEMS
			|| widgetId == InterfaceID.GeOffersSide.ITEMS
			|| widgetId == InterfaceID.Shopmain.ITEMS
			|| widgetId == InterfaceID.Shopside.ITEMS)
		{
			// The Grand Exchange search results, the GE offer setup's inventory
			// side panel, and NPC shop interfaces (both the shop's stock and the
			// player's inventory next to it) aren't backed by an ItemContainer.
			// Each slot is a child widget whose own item id is set directly.
			final Widget container = client.getWidget(widgetId);
			if (container == null)
			{
				return;
			}

			final Widget slotWidget = container.getChild(slot);
			if (slotWidget == null)
			{
				return;
			}

			final int rawItemId = slotWidget.getItemId();
			if (rawItemId <= 0 || rawItemId == ItemID.BLANKOBJECT)
			{
				return;
			}

			itemId = itemManager.canonicalize(rawItemId);
		}
		else
		{
			return;
		}

		client.createMenuEntry(-1)
			.setOption(MENU_OPTION)
			.setTarget(event.getTarget())
			.setType(MenuAction.RUNELITE)
			.onClick(e -> LinkBrowser.browse(BASE_ITEM_URL + itemId));
	}
}

package sbs.osrstracker;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

/**
 * Small panel shown while sailing, displaying the current heading-vs-movement
 * angle and a "REVERSING" warning once it crosses the configured threshold.
 */
class ReverseSailingOverlay extends OverlayPanel
{
	private Double headingDiffDegrees;
	private boolean reversing;

	@Inject
	private ReverseSailingOverlay()
	{
		setPosition(OverlayPosition.TOP_LEFT);
	}

	void update(Double headingDiffDegrees, boolean reversing)
	{
		this.headingDiffDegrees = headingDiffDegrees;
		this.reversing = reversing;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (headingDiffDegrees == null)
		{
			return null;
		}

		getPanelComponent().getChildren().clear();
		getPanelComponent().getChildren().add(TitleComponent.builder()
			.text(reversing ? "REVERSING" : "Helm Assist")
			.color(reversing ? Color.RED : Color.WHITE)
			.build());
		getPanelComponent().getChildren().add(LineComponent.builder()
			.left("Heading Δ")
			.right(String.format("%.0f°", headingDiffDegrees))
			.build());

		return super.render(graphics);
	}
}

package sbs.osrstracker;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

/**
 * Launches the full RuneLite client with OsrsTrackerPlugin sideloaded, for
 * local development/testing without publishing to the Plugin Hub.
 *
 * Run via: ./gradlew run
 */
public class OsrsTrackerPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(OsrsTrackerPlugin.class);
		RuneLite.main(args);
	}
}
